#!/usr/bin/env Rscript
all<-commandArgs(trailingOnly=FALSE);self<-normalizePath(sub("^--file=","",grep("^--file=",all,value=TRUE)[[1]]),winslash="/");root<-normalizePath(file.path(dirname(self),"../.."),winslash="/");library(shiny);`%||%`<-function(l,r)if(is.null(l)||!length(l))r else l
source(file.path(root,"app/shiny/R/process_helpers.R"));source(file.path(root,"app/shiny/R/job_manager.R"))
tmp<-file.path(tempdir(),"YTAB manager test with spaces");dir.create(file.path(tmp,"project","config"),recursive=TRUE,showWarnings=FALSE);config<-file.path(tmp,"project","config","project.yaml");writeLines("project_id: test",config);worker<-file.path(root,"scripts/local/ytab_progress_test_worker.py");python<-locate_python_executable()
shiny::testServer(function(input,output,session){manager<-new_job_manager();session$userData$manager<-manager},{m<-session$userData$manager;progress<-file.path(tmp,"success.progress.json");m$start_job(python,c(worker,"--progress-file",progress,"--items","one,two,three","--sleep-seconds","0.1"),config,"test_worker",wd=root,selected_items=c("one","two","three"),progress_file=progress);stopifnot(m$job_is_running());deadline<-Sys.time()+10;saw_item<-FALSE;saw_eta<-FALSE;while(m$job_is_running()&&Sys.time()<deadline){m$poll_job();p<-m$current_progress();saw_item<-saw_item||!is.null(p$current_item);saw_eta<-saw_eta||!is.null(p$eta_seconds);Sys.sleep(.05)};m$poll_job();stopifnot(saw_item,saw_eta,m$current_progress()$status=="success",!m$job_is_running());cancel<-file.path(tmp,"cancel.progress.json");m$start_job(python,c(worker,"--progress-file",cancel,"--items","a,b,c","--sleep-seconds","1"),config,"test_worker",wd=root,selected_items=c("a","b","c"),progress_file=cancel);Sys.sleep(.15);m$cancel_job();stopifnot(!m$job_is_running(),m$current_progress()$status=="cancelled");again<-file.path(tmp,"again.progress.json");m$start_job(python,c(worker,"--progress-file",again,"--items","z","--sleep-seconds","0.01"),config,"test_worker",wd=root,selected_items="z",progress_file=again);while(m$job_is_running()){m$poll_job();Sys.sleep(.02)};stopifnot(m$current_progress()$status=="success")})
